// Normaliza o payload e detecta pedido de atendimento humano.
const body = $input.first().json.body ?? $input.first().json;
const texto = (body.text ?? '').toLowerCase().trim();

// Gatilhos de escalonamento. Ajuste à vontade.
const GATILHOS = ['atendente', 'humano', 'pessoa', 'falar com alguem', 'falar com alguém', 'suporte'];
const querHumano = GATILHOS.some((g) => texto.includes(g));

return [{
  json: {
    conversationId: body.conversationId,
    from: body.from,
    nome: body.profileName ?? 'cliente',
    texto: body.text ?? '',
    tipo: body.type,
    querHumano,
  },
}];
